void setAppIcon(SDL_Window* win) {
    if (!win) return;
    int w = 0, h = 0, n = 0;
    unsigned char* px = stbi_load_from_memory(kIconPng, (int)sizeof kIconPng, &w, &h, &n, 4);
    if (!px) return;
    SDL_Surface* s = SDL_CreateRGBSurfaceWithFormatFrom(px, w, h, 32, w * 4, SDL_PIXELFORMAT_RGBA32);
    if (s) {
        SDL_SetWindowIcon(win, s);
        SDL_FreeSurface(s);
    }
    stbi_image_free(px);
}
